mapper.insert:
INSERT IGNORE INTO message_translations (
    msg_hash
  , disaster_code
  , region
  , original_text
  , easy_text
  , tts_text
  , action_text
  , pictogram_codes
  , received_at
) VALUES (
    #{msgHash}
  , #{disasterCode}
  , #{region}
  , #{originalText}
  , #{easyText}
  , #{ttsText}
  , #{actionText}
  , #{pictogramCodes}
  , #{receivedAt}
)
